// G2 - SOMENTE LEITURA. Guarda os sinais booleanos do s7 in do Processo com o horário da observação.
const CAMPOS = [
    // DB2 (interface com o MES)
    'recebidoOP', 'cancelOP', 'finishOP', 'startOP', 'ocupado', 'aguardando', 'manual',
    'emergencia', 'emergenciaAtivada', 'comutadorAutomatico', 'homeX', 'homeY', 'servoX', 'servoY', 'condicaoIniciar',
    // DB101 (entradas e saídas da estação Processo)
    'segurancaOK', 'eixoZAvancado', 'eixoZRecuado', 'sensorVacuoManipulador', 'sensorVacuo', 'chaveAutomatico',
    'botaoVerde', 'botaoVermelho', 'atuadoresPosicaoOK', 'atuadoresOcupado', 'avancaEixoZ', 'acionaVacuoManipulador',
    'acionaVacuoMesa', 'esteira1', 'esteira2', 'stopper1', 'stopper2', 'triggerAtuador'
];
const p = msg.payload;
if (p === null || typeof p !== 'object' || Array.isArray(p)) {
    node.status({ fill: 'red', shape: 'ring', text: 'payload não é objeto' });
    return null;
}
const cache = global.get('g2_n2_cache_leitura') || {};
const agora = Date.now();
let recebidos = 0;
for (const campo of CAMPOS) {
    if (Object.prototype.hasOwnProperty.call(p, campo) && typeof p[campo] === 'boolean') {
        cache[campo] = { valor: p[campo], observadoEm: agora };
        recebidos++;
    }
}
if (recebidos > 0) {
    global.set('g2_n2_cache_leitura', cache);
    node.status({ fill: 'green', shape: 'dot', text: recebidos + '/' + CAMPOS.length + ' sinais às ' + new Date(agora).toLocaleTimeString() });
} else {
    node.status({ fill: 'yellow', shape: 'ring', text: 'nenhum campo conhecido; chaves: ' + Object.keys(p).slice(0, 4).join(',') });
}
return null;

// G2 - SOMENTE LEITURA. GET /api/g2/processo/telemetria: sinais observados nos últimos 3 s.
const CAMPOS = [
    // DB2 (interface com o MES)
    'recebidoOP', 'cancelOP', 'finishOP', 'startOP', 'ocupado', 'aguardando', 'manual',
    'emergencia', 'emergenciaAtivada', 'comutadorAutomatico', 'homeX', 'homeY', 'servoX', 'servoY', 'condicaoIniciar',
    // DB101 (entradas e saídas da estação Processo)
    'segurancaOK', 'eixoZAvancado', 'eixoZRecuado', 'sensorVacuoManipulador', 'sensorVacuo', 'chaveAutomatico',
    'botaoVerde', 'botaoVermelho', 'atuadoresPosicaoOK', 'atuadoresOcupado', 'avancaEixoZ', 'acionaVacuoManipulador',
    'acionaVacuoMesa', 'esteira1', 'esteira2', 'stopper1', 'stopper2', 'triggerAtuador'
];
const VALIDADE_MS = 3000;
const cache = global.get('g2_n2_cache_leitura') || {};
const agora = Date.now();
const sinais = {};
const observadosEm = {};
for (const campo of CAMPOS) {
    const item = cache[campo];
    if (!item || typeof item.valor !== 'boolean' || typeof item.observadoEm !== 'number' || !isFinite(item.observadoEm)) continue;
    const idade = agora - item.observadoEm;
    if (idade < 0 || idade > VALIDADE_MS) continue;
    sinais[campo] = item.valor;
    observadosEm[campo] = new Date(item.observadoEm).toISOString();
}
const temDados = Object.keys(sinais).length > 0;
msg.statusCode = temDados ? 200 : 503;
msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
msg.payload = {
    status: temDados ? 'leitura_parcial' : 'sem_dados_recentes',
    estacao: 'PROCESSO',
    timestampConsulta: new Date(agora).toISOString(),
    dadosValidos: temDados,
    sinais,
    observadosEm
};
node.status({ fill: temDados ? 'green' : 'grey', shape: 'dot', text: msg.statusCode + ' · ' + Object.keys(sinais).length + ' sinais' });
return msg;
